#!/usr/bin/env python3
"""Compute GC content over sliding windows of sequences in a FASTA file."""

import argparse
import sys


def read_fasta(path):
    seqid = None
    chunks = []
    with open(path) as fh:
        for line in fh:
            line = line.rstrip("\n")
            if line.startswith(">"):
                if seqid is not None:
                    yield seqid, "".join(chunks)
                seqid = line[1:].split()[0] if len(line) > 1 else ""
                chunks = []
            elif seqid is not None:
                chunks.append(line.strip())
    if seqid is not None:
        yield seqid, "".join(chunks)


def window_gc(seq):
    """GC fraction of a window, excluding N bases from numerator and denominator."""
    a = c = g = t = 0
    for base in seq:
        b = base.upper()
        if b == "A":
            a += 1
        elif b == "C":
            c += 1
        elif b == "G":
            g += 1
        elif b == "T":
            t += 1
    total = a + c + g + t
    if total == 0:
        return "NA"
    return f"{(g + c) / total:.4f}"


def main(argv=None):
    parser = argparse.ArgumentParser(description="Sliding-window GC content calculator")
    parser.add_argument("fasta", help="Path to FASTA file")
    parser.add_argument("--window", type=int, required=True, help="Window size W")
    parser.add_argument("--step", type=int, required=True, help="Step size S")
    args = parser.parse_args(argv)

    if args.window <= 0 or args.step <= 0:
        parser.error("--window and --step must be positive integers")

    out = sys.stdout
    for seqid, seq in read_fasta(args.fasta):
        n = len(seq)
        for start in range(0, n - args.window + 1, args.step):
            win = seq[start : start + args.window]
            if len(win) < args.window:
                break  # only full-length windows
            out.write(f"{seqid}\t{start}\t{window_gc(win)}\n")


if __name__ == "__main__":
    main()

